application.css:
* {
  box-sizing: border-box;
}

:root {
  color: #1f2937;
  background: #eef2f7;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  line-height: 1.5;
}

body {
  margin: 0;
  min-width: 0;
}

.app-shell {
  width: min(100% - 2rem, 48rem);
  margin: 0 auto;
  padding: 3rem 0;
}

.app-header {
  margin-bottom: 2rem;
}

h1, h2, p {
  margin-top: 0;
}

h1 {
  margin-bottom: 0.35rem;
  color: #172554;
  font-size: clamp(2rem, 6vw, 3rem);
  line-height: 1.1;
}

h2 {
  margin-bottom: 1rem;
  color: #1e3a8a;
  font-size: 1.3rem;
}

.subtitle {
  margin-bottom: 0;
  color: #475569;
}

.task-entry,
.tasks-section {
  margin-bottom: 1.5rem;
  padding: 1.5rem;
  border: 1px solid #cbd5e1;
  border-radius: 0.75rem;
  background: #ffffff;
  box-shadow: 0 2px 8px rgb(15 23 42 / 0.06);
}

.entry-row {
  display: flex;
  align-items: end;
  gap: 0.75rem;
}

.field-group {
  flex: 1;
}

label {
  display: block;
  margin-bottom: 0.4rem;
  font-weight: 600;
}

input[type="text"] {
  width: 100%;
  min-height: 2.75rem;
  padding: 0.6rem 0.75rem;
  border: 2px solid #94a3b8;
  border-radius: 0.4rem;
  color: #111827;
  background: #fff;
  font: inherit;
}

button {
  min-height: 2.75rem;
  padding: 0.6rem 1rem;
  border: 0;
  border-radius: 0.4rem;
  color: #fff;
  background: #1d4ed8;
  font: inherit;
  font-weight: 700;
  cursor: pointer;
}

button:hover {
  background: #1e40af;
}

button:focus-visible,
input:focus-visible {
  outline: 3px solid #f59e0b;
  outline-offset: 2px;
}

.form-error {
  margin: 0.65rem 0 0;
  color: #b91c1c;
  font-weight: 600;
}

.tasks-heading-row {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 1rem;
}

.count {
  margin-bottom: 1rem;
  color: #475569;
  font-weight: 600;
}

.task-list {
  display: grid;
  gap: 0.65rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.task-item {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  min-width: 0;
  padding: 0.75rem;
  border: 1px solid #cbd5e1;
  border-radius: 0.5rem;
  background: #f8fafc;
}

.task-toggle {
  width: 1.2rem;
  height: 1.2rem;
  flex: 0 0 auto;
  accent-color: #1d4ed8;
}

.task-text {
  flex: 1;
  min-width: 0;
  overflow-wrap: anywhere;
}

.task-item.completed .task-text {
  color: #64748b;
  text-decoration: line-through;
}

.delete-button {
  min-height: 2.25rem;
  padding: 0.4rem 0.7rem;
  background: #b91c1c;
  font-size: 0.9rem;
}

.delete-button:hover {
  background: #991b1b;
}

.empty-message {
  margin: 0;
  color: #64748b;
}

@media (max-width:  thirtyrem) {
  .entry-row {
    align-items: stretch;
    flex-direction: column;
  }

  .tasks-heading-row {
    align-items: flex-start;
    flex-direction: column;
    gap: 0;
  }
}

@media (max-width: 30rem) {
  .app-shell {
    width: min(100% - 1rem, 48rem);
    padding: 1.5rem 0;
  }

  .task-entry,
  .tasks-section {
    padding: 1rem;
  }
}

application.javascript:
(() => {
  "use strict";

  const tasks = [];
  let nextTaskId = 1;

  function getElements() {
    return {
      form: document.getElementById("task-form"),
      input: document.querySelector('[data-testid="task-input"]'),
      error: document.getElementById("form-error"),
      list: document.querySelector('[data-testid="task-list"]'),
      count: document.querySelector('[data-testid="incomplete-count"]'),
      emptyMessage: document.getElementById("empty-message")
    };
  }

  function showError(message, elements) {
    elements.error.textContent = message;
    elements.error.hidden = false;
  }

  function clearError(elements) {
    elements.error.textContent = "";
    elements.error.hidden = true;
  }

  function addTask(text) {
    tasks.push({ id: nextTaskId, text, completed: false });
    nextTaskId += 1;
  }

  function createTaskElement(task) {
    const item = document.createElement("li");
    item.className = "task-item";
    item.dataset.testid = "task";
    item.dataset.completed = String(task.completed);

    const checkbox = document.createElement("input");
    checkbox.type = "checkbox";
    checkbox.className = "task-toggle";
    checkbox.dataset.testid = "task-complete";
    checkbox.id = `task-${task.id}`;
    checkbox.checked = task.completed;
    checkbox.setAttribute("aria-label", `Mark ${task.text} as complete`);
    checkbox.addEventListener("change", () => {
      task.completed = checkbox.checked;
      renderTasks();
    });

    const label = document.createElement("label");
    label.className = "task-text";
    label.dataset.testid = "task-text";
    label.htmlFor = checkbox.id;
    label.textContent = task.text;

    const deleteButton = document.createElement("button");
    deleteButton.type = "button";
    deleteButton.className = "delete-button";
    deleteButton.dataset.testid = "task-delete";
    deleteButton.textContent = "Delete";
    deleteButton.setAttribute("aria-label", `Delete ${task.text}`);
    deleteButton.addEventListener("click", () => {
      const index = tasks.findIndex((candidate) => candidate.id === task.id);
      if (index !== -1) tasks.splice(index, 1);
      renderTasks();
    });

    item.append(checkbox, label, deleteButton);
    if (task.completed) item.classList.add("completed");
    return item;
  }

  function renderTasks() {
    const elements = getElements();
    elements.list.replaceChildren(...tasks.map(createTaskElement));
    elements.count.textContent = String(tasks.filter((task) => !task.completed).length);
    elements.emptyMessage.hidden = tasks.length > 0;
  }

  function handleSubmit(event) {
    event.preventDefault();
    const elements = getElements();
    const text = elements.input.value.trim();
    if (!text) {
      showError("Enter a task before adding it.", elements);
      elements.input.focus();
      return;
    }
    clearError(elements);
    addTask(text);
    elements.input.value = "";
    renderTasks();
    elements.input.focus();
  }

  function initialise() {
    const elements = getElements();
    elements.form.addEventListener("submit", handleSubmit);
    renderTasks();
  }

  document.addEventListener("DOMContentLoaded", initialise);
})();
